import json # Read measured experiment evidence without synthesizing mechanical results.
import numpy as np # Aggregate the fixed physical test denominator.
import matplotlib # Use a deterministic headless scientific plotting backend.
matplotlib.use('Agg') # Render reproducible standalone artifacts without a display.
import matplotlib.pyplot as plt # Plot actual scalar verification metrics rather than invented field contours.
from fem import REPO,FAMILIES # Preserve registered family ordering.
ROOT=REPO/'build/residual-online-20261024';summary=json.loads((ROOT/'summary.json').read_text());rows=summary['all_case_results'];raw=summary['raw_neural']['all_case_results'];methods=['neural_warm','reduced_warm','zero_cold'];names=['Neural + two-level Krylov','Reduced + two-level Krylov','Zero + two-level Krylov'];colors=['#2465a8','#d18f26','#438c70'];x=np.arange(len(FAMILIES)) # Bind every panel to the audited 128 physical cases.
fig,axes=plt.subplots(2,2,figsize=(16,10),constrained_layout=True);fig.suptitle('Frozen local-bridge benchmark: 128 cases, 384 corrected solutions',fontsize=18) # Present accuracy and cost together without implying engineering release.
for axis,key,gate,title in [(axes[0,0],'relative_residual',1e-7,'Maximum full equilibrium residual'),(axes[0,1],'relative_field_error',1e-5,'Maximum displacement relative error')]: # Keep residual and field accuracy distinct for ill-conditioned systems.
    raw_values=[max(v[key] for v in raw if v['family']==family) for family in FAMILIES];corrected=[max(v[key] for v in rows if v['family']==family) for family in FAMILIES];axis.bar(x-.19,raw_values,.38,color='#a45252',label='Raw neural');axis.bar(x+.19,corrected,.38,color='#2465a8',label='All corrected starts: worst case');axis.axhline(gate,color='black',linestyle='--',linewidth=1,label='Frozen acceptance gate');axis.set_yscale('log');axis.set_xticks(x,FAMILIES,rotation=25,ha='right');axis.set_title(title);axis.grid(axis='y',alpha=.2);axis.legend(fontsize=8) # Show actual worst cases across both test and out-of-domain inputs.
for index,(method,label,color) in enumerate(zip(methods,names,colors)): # Compare all initializations under the identical iteration budget.
    values=[np.mean([v['iterations'] for v in rows if v['family']==family and v['method']==method]) for family in FAMILIES];axes[1,0].bar(x+(index-1)*.25,values,.25,label=label,color=color) # Display observed average Krylov effort without hiding the zero-start baseline.
axes[1,0].set_xticks(x,FAMILIES,rotation=25,ha='right');axes[1,0].set_title('Mean actual Krylov iterations per case');axes[1,0].set_ylabel('Iterations');axes[1,0].grid(axis='y',alpha=.2);axes[1,0].legend(fontsize=8) # Retain a common count scale for direct comparison.
bottom=np.zeros(3) # Accumulate each standalone method's complete measured online work.
for key,label,color in [('assembly_seconds_shared','Full target assembly','#94b8d9'),('coarse_setup_seconds_shared','384D coarse setup/factor','#696dab'),('initial_seconds','Actual initialization','#e0b56a'),('seconds','All iterative attempts','#4c8b72')]: # Disclose every charged online stage, including small factorizations and inference.
    values=np.array([sum(v[key] for v in rows if v['method']==method) for method in methods]);axes[1,1].bar(np.arange(3),values,bottom=bottom,label=label,color=color);bottom+=values # Plot real wall-clock sums with target setup charged once per standalone method.
axes[1,1].set_xticks(np.arange(3),['Neural warm','Reduced warm','Zero cold']);axes[1,1].set_title('Measured online compute stages: 128 cases');axes[1,1].set_ylabel('Measured seconds');axes[1,1].grid(axis='y',alpha=.2);axes[1,1].legend(fontsize=8) # Present noisy shared-host costs without asserting controlled speedup.
fig.text(.5,-.015,'Offline preparation is itemized separately; online I/O/bookkeeping excluded. Shared-host timing; no neural-only or engineering-release claim.',ha='center',fontsize=10);fig.savefig(ROOT/'residual_online_verification.png',dpi=180,bbox_inches='tight');fig.savefig(ROOT/'residual_online_verification.svg',bbox_inches='tight');plt.close(fig) # Save faithful scientific scalar charts suitable for a report.
